<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$metrics=['open_tickets'=>(int)$db->query("SELECT COUNT(*) FROM support_tickets WHERE status NOT IN ('resolved','closed')")->fetchColumn(),'sla_risks'=>(int)$db->query("SELECT COUNT(*) FROM support_tickets WHERE due_at IS NOT NULL AND due_at<NOW() AND status NOT IN ('resolved','closed')")->fetchColumn(),'overdue_projects'=>(int)$db->query("SELECT COUNT(*) FROM client_projects WHERE due_date IS NOT NULL AND due_date<CURDATE() AND status NOT IN ('completed','cancelled')")->fetchColumn(),'outstanding_invoice_balance'=>(float)$db->query("SELECT COALESCE(SUM(balance_due),0) FROM invoices WHERE status IN ('sent','partially_paid','overdue')")->fetchColumn(),'pipeline_value'=>(float)$db->query("SELECT COALESCE(SUM(estimated_value),0) FROM leads WHERE status IN ('new','contacted','proposal')")->fetchColumn(),'overdue_invoices'=>(int)$db->query("SELECT COUNT(*) FROM invoices WHERE status='overdue' AND balance_due>0")->fetchColumn()];$rules=$db->prepare("SELECT * FROM bi_alert_rules WHERE metric=? AND is_active=1");foreach($metrics as $metric=>$value){$rules->execute([$metric]);foreach($rules->fetchAll(PDO::FETCH_ASSOC) as $r){$v=(float)$value;$t=(float)$r['threshold'];$hit=match($r['operator']){'>'=>$v>$t,'>='=>$v>=$t,'<' =>$v<$t,'<='=>$v<=$t,'='=>$v===$t,default=>false};if($hit){$dedupe=$db->prepare('SELECT id FROM bi_alert_events WHERE rule_id=? AND created_at>=DATE_SUB(NOW(),INTERVAL 1 DAY) LIMIT 1');$dedupe->execute([(int)$r['id']]);if(!$dedupe->fetch()){$q2=$db->prepare('INSERT INTO bi_alert_events(rule_id,metric_value,message) VALUES(?,?,?)');$q2->execute([(int)$r['id'],$value,$r['name'].': '.$metric.'='.$value]);}}}}if((int)$db->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='automation_rules'")->fetchColumn()){foreach($db->query('SELECT id FROM automation_rules WHERE is_active=1')->fetchAll(PDO::FETCH_COLUMN) as $ruleId){$started=date('Y-m-d H:i:s');try{$q=$db->prepare('INSERT INTO automation_runs(rule_id,status,event_payload,result_message,started_at,finished_at) VALUES(?,?,?,?,?,NOW())');$q->execute([(int)$ruleId,'success',json_encode($metrics),'Phase 14 metric evaluation completed',$started]);$db->prepare('UPDATE automation_rules SET last_run_at=NOW() WHERE id=?')->execute([(int)$ruleId]);}catch(Throwable $e){error_log('Phase14 automation rule '.$ruleId.' failed: '.$e->getMessage());}}}echo 'Phase 14 automation completed at '.date('c').PHP_EOL;